from openpyxl import load_workbook
from pathlib import Path
src='/root/data/workbook.xlsx'
out='/root/output/result.xlsx'
allowed=set()
for r1,r2 in [(12,17),(19,24),(26,31),(35,40),(42,47),(50,50)]:
    for r in range(r1,r2+1):
        for c in range(8,13):
            allowed.add((r,c))
wb1=load_workbook(src, data_only=False)
wb2=load_workbook(out, data_only=False)
problems=[]
for s in wb1.sheetnames:
    if s not in wb2.sheetnames:
        problems.append(f'missing sheet {s}')
        continue
    ws1, ws2 = wb1[s], wb2[s]
    maxr=max(ws1.max_row, ws2.max_row)
    maxc=max(ws1.max_column, ws2.max_column)
    for r in range(1,maxr+1):
        for c in range(1,maxc+1):
            if s=='Task' and (r,c) in allowed:
                continue
            if ws1.cell(r,c).value != ws2.cell(r,c).value:
                problems.append(f'{s}!{ws1.cell(r,c).coordinate}: {ws1.cell(r,c).value!r} -> {ws2.cell(r,c).value!r}')
print('Sheets preserved:', wb2.sheetnames)
print('Cell value changes outside allowed ranges:', len(problems))
if problems:
    print('\n'.join(problems[:50]))
print('Output exists:', Path(out).exists(), 'size:', Path(out).stat().st_size)
